# frozen_string_literal: true
require 'rails_helper'
require 'benchmark'

RSpec.describe 'factory profiling' do
  def measure(name, n=20)
    # warmup
    2.times { yield }
    t = Benchmark.realtime { n.times { yield } }
    puts format("PROFILE %-35s n=%d total=%.3fs per=%.1fms", name, n, t, t*1000.0/n)
  end

  it 'profiles' do
    Sidekiq.testing!(:fake) { }
    measure('tag') { Fabricate(:tag) }
    measure('account local') { Fabricate(:account) }
    measure('remote_account') { Fabricate(:remote_account) }
    measure('user') { Fabricate(:user) }
    measure('account no-user? remote via domain') { Fabricate(:account, domain: 'example.com') }
    acct = Fabricate(:account)
    measure('status existing acct') { Fabricate(:status, account: acct) }
    measure('status new acct') { Fabricate(:status) }
    measure('bookmark existing') { s=Fabricate(:status, account: acct); Fabricate(:bookmark, account: acct, status: s) }
    measure('follow existing') { a=Fabricate(:account); Fabricate(:follow, account: acct, target_account: a) }
    measure('media_attachment existing acct') { Fabricate(:media_attachment, account: acct) }
    measure('media_attachment build') { Fabricate.build(:media_attachment, account: acct) }
    measure('notification') { Fabricate(:notification) }
    measure('poll existing') { s=nil; Fabricate(:poll, account: acct) }
    measure('favourite existing') { s=Fabricate(:status, account: acct); Fabricate(:favourite, account: acct, status: s) }
    measure('access_token user') { Fabricate(:accessible_access_token, resource_owner_id: acct.user.id) rescue puts $! }
    measure('application') { Fabricate(:application) }
    measure('list') { Fabricate(:list, account: acct) rescue puts $! }
    puts format("COUNTS Account=%d User=%d Status=%d Bookmark=%d LoginActivity=%d Keypair=%d", Account.count, User.count, Status.count, Bookmark.count, LoginActivity.count, Keypair.count)
  end
end
RUBY
