# frozen_string_literal: true
require 'rails_helper'
require 'benchmark'
RSpec.describe 'factory profiling2' do
  def measure(name, n=30)
    2.times { yield }
    t = Benchmark.realtime { n.times { yield } }
    puts format("PROFILE %-45s n=%d total=%.3fs per=%.1fms", name, n, t, t*1000.0/n)
  end
  it 'profiles' do
    acct = Fabricate(:account)
    puts "acct counts A=#{Account.count} U=#{User.count} K=#{Keypair.count} LA=#{LoginActivity.count}"
    measure('Status.create! existing acct (no fab)') { Status.create!(account: acct, text: 'hi') }
    measure('Fabricate.build(:status existing).save!') { Fabricate.build(:status, account: acct).save! }
    measure('Fabricate(:status existing)') { Fabricate(:status, account: acct) }
    measure('Fabricate.build(:status existing) only') { Fabricate.build(:status, account: acct) }
    measure('Fabricate.build(:account) only') { Fabricate.build(:account) }
    measure('Fabricate(:account)') { Fabricate(:account) }
    measure('Fabricate.build(:user, account:nil?) acct') { Fabricate.build(:user) }
    measure('Fabricate(:user)') { Fabricate(:user) }
    measure('User.create! manual') { a=Fabricate.build(:account, user: nil); User.create!(account: a, email: "x#{SecureRandom.hex(4)}@e.com", password: '123456789', agreement: true, confirmed_at: Time.zone.now) }
    measure('BCrypt hash') { BCrypt::Password.create('123456789', cost: BCrypt::Engine::MIN_COST) rescue puts $! }
    measure('Faker username') { Faker::Internet.user_name(separators: %w(_)) }
    measure('Faker email') { Faker::Internet.email }
    measure('Faker device_token') { Faker::Internet.device_token }
    measure('Faker ip+ua') { Faker::Internet.ip_v4_address; Faker::Internet.user_agent }
    measure('Faker Lorem sentence') { Faker::Lorem.sentence }
    measure('Faker Lorem paragraph') { Faker::Lorem.paragraph }
    measure('media build only') { Fabricate.build(:media_attachment, account: acct) }
    measure('media create existing') { Fabricate(:media_attachment, account: acct) }
    m = Fabricate.build(:media_attachment, account: acct)
    puts "media file styles? #{m.file.styles.keys rescue $!} type=#{m.type}"
    measure('custom_emoji create') { Fabricate(:custom_emoji) }
    measure('preview_card create') { Fabricate(:preview_card) }
    puts format("COUNTS A=%d U=%d S=%d B=%d LA=%d K=%d MA=%d", Account.count, User.count, Status.count, Bookmark.count, LoginActivity.count, Keypair.count, MediaAttachment.count)
  end
end
